export function Primitive({
  primitiveType = "{{primitiveType}}",
  styled = {{styled}},
  accent = "{{accent}}",
}) {
  const styledBtn = styled ? { padding: "9px 16px", borderRadius: 8, border: "none", background: accent, color: "#241430", fontWeight: 600, cursor: "pointer" } : {};
  const styledInput = styled ? { padding: "9px 12px", borderRadius: 8, border: `1.5px solid ${accent}`, width: "100%", boxSizing: "border-box" } : {};
  return (
    <div style={{ width: "100%", maxWidth: 320, padding: 18, background: "#FAF7F2", border: "1px solid #24143022", borderRadius: 12, fontFamily: "system-ui, sans-serif", fontSize: 13, color: "#241430aa" }}>
      {primitiveType === "button" && <button type="button" style={styledBtn}>Continue</button>}
      {primitiveType === "checkbox" && <label><input type="checkbox" checked readOnly disabled /> Remember me</label>}
      {primitiveType === "input" && <input style={styledInput} placeholder="Email address" disabled />}
      <p style={{ margin: "14px 0 0" }}>{styled ? "Composed" : "Raw"} &mdash; every composed component still boils down to a primitive</p>
    </div>
  );
}
